CREATE TABLE product(id BIGINT PRIMARY KEY,name VARCHAR(100) NOT NULL,price_cents BIGINT NOT NULL,stock INT NOT NULL,CHECK(stock>=0),CHECK(price_cents>0));
INSERT INTO product VALUES(1,'机械键盘',29900,1000),(2,'无线鼠标',12900,1000),(3,'便携显示器',89900,1000);
CREATE TABLE shop_order(id BIGINT AUTO_INCREMENT PRIMARY KEY,idempotency_key VARCHAR(80) NOT NULL UNIQUE,request_hash VARCHAR(160) NOT NULL,product_id BIGINT NOT NULL,quantity INT NOT NULL,region VARCHAR(20) NOT NULL,total_cents BIGINT NOT NULL,status VARCHAR(20) NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),fulfilled_at DATETIME(6),FOREIGN KEY(product_id) REFERENCES product(id),CHECK(quantity>0));
CREATE TABLE stock_movement(id BIGINT AUTO_INCREMENT PRIMARY KEY,product_id BIGINT NOT NULL,order_id BIGINT,delta INT NOT NULL,reason VARCHAR(20) NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),UNIQUE KEY uq_order_reason(order_id,reason),FOREIGN KEY(product_id) REFERENCES product(id),FOREIGN KEY(order_id) REFERENCES shop_order(id));
CREATE TABLE order_outbox(id BIGINT AUTO_INCREMENT PRIMARY KEY,order_id BIGINT NOT NULL UNIQUE,status VARCHAR(20) NOT NULL DEFAULT 'PENDING',lease_token VARCHAR(36),locked_until DATETIME(6),next_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),attempts INT NOT NULL DEFAULT 0,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),FOREIGN KEY(order_id) REFERENCES shop_order(id));
CREATE TABLE fulfillment_receipt(event_id BIGINT PRIMARY KEY,order_id BIGINT NOT NULL UNIQUE,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),FOREIGN KEY(order_id) REFERENCES shop_order(id));
